package com.matchinglootbeams;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Boots the full RuneLite client with this plugin side-loaded.
 * Run this main() from IntelliJ to develop and debug the plugin.
 */
public class MatchingLootbeamsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MatchingLootbeamsPlugin.class);
		RuneLite.main(args);
	}
}

package com.matchinglootbeams;

import java.awt.Color;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DominantColorTest
{
	private static final Color FALLBACK = new Color(0xFFFF00);

	@Test
	public void returnsFallbackForFullyTransparentImage()
	{
		BufferedImage img = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		// default is fully transparent black
		assertEquals(FALLBACK, DominantColor.extract(img, FALLBACK));
	}

	@Test
	public void returnsFallbackForNullImage()
	{
		assertEquals(FALLBACK, DominantColor.extract(null, FALLBACK));
	}

	@Test
	public void picksDominantHueOverBackgroundClutter()
	{
		BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		// Fill 80% with vivid red, 20% with mid-gray (which should lose due to low saturation weight).
		for (int y = 0; y < 16; y++)
		{
			for (int x = 0; x < 16; x++)
			{
				int rgb;
				if (x < 13)
				{
					rgb = 0xFFCC2222; // vivid red
				}
				else
				{
					rgb = 0xFF888888; // gray
				}
				img.setRGB(x, y, rgb);
			}
		}

		Color result = DominantColor.extract(img, FALLBACK);
		assertTrue("expected red-dominant, got " + result, result.getRed() > result.getGreen() + 40);
		assertTrue("expected red-dominant, got " + result, result.getRed() > result.getBlue() + 40);
	}

	@Test
	public void ignoresTransparentAndNearBlackPixels()
	{
		BufferedImage img = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		// 4x8 transparent, 4x8 black outline-ish, then a single bright blue pixel.
		for (int y = 0; y < 8; y++)
		{
			for (int x = 0; x < 8; x++)
			{
				if (x < 4)
				{
					img.setRGB(x, y, 0x00000000);
				}
				else
				{
					img.setRGB(x, y, 0xFF050505);
				}
			}
		}
		// Single saturated blue pixel — should still win the histogram.
		img.setRGB(7, 7, 0xFF2244EE);

		Color result = DominantColor.extract(img, FALLBACK);
		assertTrue("expected blue-dominant, got " + result, result.getBlue() > result.getRed() + 40);
		assertTrue("expected blue-dominant, got " + result, result.getBlue() > result.getGreen() + 40);
	}
}

package com.matchinglootbeams;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.function.Consumer;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Matching Lootbeams",
	description = "Colors ground item loot beams by the item's dominant sprite color",
	tags = {"ground", "items", "color", "loot", "beam"}
)
public class MatchingLootbeamsPlugin extends Plugin
{
	private static final int MAX_LOAD_RETRIES = 30;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ItemManager itemManager;
	@Inject private MatchingLootbeamsConfig config;

	private final ConcurrentMap<Integer, Color> colorCache = new ConcurrentHashMap<>();
	private final ConcurrentMap<Integer, Integer> loadAttempts = new ConcurrentHashMap<>();

	// Beams are 3D scene objects — accessed only on the client thread.
	private final Map<TileItem, Lootbeam> beams = new HashMap<>();

	@Provides
	@SuppressWarnings("unused")
	MatchingLootbeamsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MatchingLootbeamsConfig.class);
	}

	@Override
	protected void shutDown()
	{
		clientThread.invoke(this::destroyAllBeams);
		colorCache.clear();
		loadAttempts.clear();
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			destroyAllBeams();
		}
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onItemSpawned(ItemSpawned event)
	{
		TileItem item = event.getItem();
		Tile tile = event.getTile();
		int itemId = item.getId();

		if (config.minValue() > 0)
		{
			ItemComposition comp = itemManager.getItemComposition(itemId);
			int shopValue = comp.getPrice();
			int gePrice = itemManager.getItemPrice(itemId);
			int unitValue = Math.max(shopValue, gePrice);
			long totalValue = (long) unitValue * item.getQuantity();
			if (totalValue < config.minValue())
			{
				return;
			}
		}

		ensureColorLoaded(itemId, color -> spawnBeam(item, tile, color));
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onItemDespawned(ItemDespawned event)
	{
		destroyBeam(event.getItem());
	}

	private void spawnBeam(TileItem item, Tile tile, Color color)
	{
		// Runs on the client thread (invoked from ensureColorLoaded's invokeLater).
		if (!config.showBeam())
		{
			return;
		}
		if (beams.containsKey(item))
		{
			return;
		}

		WorldPoint wp = tile.getWorldLocation();
		Lootbeam beam = new Lootbeam(client, clientThread, wp, color, Lootbeam.Style.MODERN);
		beams.put(item, beam);
	}

	private void destroyBeam(TileItem item)
	{
		Lootbeam beam = beams.remove(item);
		if (beam != null)
		{
			clientThread.invoke(beam::remove);
		}
	}

	private void destroyAllBeams()
	{
		for (Lootbeam beam : beams.values())
		{
			beam.remove();
		}
		beams.clear();
	}

	private void ensureColorLoaded(int itemId, Consumer<Color> onReady)
	{
		Color cached = colorCache.get(itemId);
		if (cached != null)
		{
			clientThread.invoke(() -> onReady.accept(cached));
			return;
		}

		clientThread.invokeLater(() -> {
			Color have = colorCache.get(itemId);
			if (have != null)
			{
				onReady.accept(have);
				return true;
			}

			BufferedImage image = itemManager.getImage(itemId);
			Color extracted = image == null ? null : DominantColor.extract(image, null);
			if (extracted != null)
			{
				colorCache.put(itemId, extracted);
				loadAttempts.remove(itemId);
				onReady.accept(extracted);
				return true;
			}

			int attempts = loadAttempts.merge(itemId, 1, Integer::sum);
			if (attempts >= MAX_LOAD_RETRIES)
			{
				Color fb = config.fallbackColor();
				colorCache.put(itemId, fb);
				loadAttempts.remove(itemId);
				onReady.accept(fb);
				return true;
			}
			return false;
		});
	}
}

package com.matchinglootbeams;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(MatchingLootbeamsConfig.GROUP)
public interface MatchingLootbeamsConfig extends Config
{
	String GROUP = "matchinglootbeams";

	@ConfigItem(
		keyName = "showBeam",
		name = "Show beam",
		description = "Render a 3D loot beam at each tracked ground item, colored by its dominant sprite color. " +
			"Disable Ground Items' built-in beams in its config to avoid duplicates.",
		position = 1
	)
	default boolean showBeam()
	{
		return true;
	}

	@ConfigItem(
		keyName = "minValue",
		name = "Min value",
		description = "Skip items whose total value is below this. " +
			"Per-item value is max(shop value, GE price), multiplied by the stack quantity. " +
			"0 shows everything.",
		position = 2
	)
	@Range(min = 0, max = 2_147_483_647)
	default int minValue()
	{
		return 0;
	}

	@Alpha
	@ConfigItem(
		keyName = "fallbackColor",
		name = "Fallback color",
		description = "Used when no dominant color can be extracted (e.g. monochrome sprites or load failure).",
		position = 3
	)
	default Color fallbackColor()
	{
		return new Color(0xFFFFFF);
	}
}

package com.matchinglootbeams;

import java.awt.Color;
import java.awt.image.BufferedImage;

/**
 * Extracts a representative color from an item sprite by quantizing pixels into
 * a coarse RGB histogram and returning the centroid of the heaviest bucket.
 *
 * Pixels are weighted by saturation so neutral grays (UI shadows, outlines)
 * do not dominate visually-vivid items. Near-transparent and near-black /
 * near-white pixels are skipped.
 */
public final class DominantColor
{
	// 4 bits per channel → 16 levels per channel → 4096 buckets total.
	private static final int BITS_PER_CHANNEL = 4;
	private static final int LEVELS = 1 << BITS_PER_CHANNEL;
	private static final int SHIFT = 8 - BITS_PER_CHANNEL;
	private static final int BUCKETS = LEVELS * LEVELS * LEVELS;

	private static final int ALPHA_THRESHOLD = 128;
	private static final int MIN_LUMA = 24;
	private static final int MAX_LUMA = 240;

	private DominantColor()
	{
	}

	public static Color extract(BufferedImage image, Color fallback)
	{
		if (image == null || image.getWidth() == 0 || image.getHeight() == 0)
		{
			return fallback;
		}

		final int w = image.getWidth();
		final int h = image.getHeight();
		final int[] pixels = image.getRGB(0, 0, w, h, null, 0, w);

		final double[] weight = new double[BUCKETS];
		final int[] count = new int[BUCKETS];
		final long[] rSum = new long[BUCKETS];
		final long[] gSum = new long[BUCKETS];
		final long[] bSum = new long[BUCKETS];

		for (int argb : pixels)
		{
			final int a = (argb >>> 24) & 0xFF;
			if (a < ALPHA_THRESHOLD)
			{
				continue;
			}

			final int r = (argb >>> 16) & 0xFF;
			final int g = (argb >>> 8) & 0xFF;
			final int b = argb & 0xFF;

			final int luma = (r * 299 + g * 587 + b * 114) / 1000;
			if (luma < MIN_LUMA || luma > MAX_LUMA)
			{
				continue;
			}

			final int max = Math.max(r, Math.max(g, b));
			final int min = Math.min(r, Math.min(g, b));
			final double saturation = max == 0 ? 0.0 : (max - min) / (double) max;
			final double pixelWeight = 0.05 + saturation * saturation;

			final int bucket = ((r >>> SHIFT) * LEVELS + (g >>> SHIFT)) * LEVELS + (b >>> SHIFT);
			weight[bucket] += pixelWeight;
			count[bucket]++;
			rSum[bucket] += r;
			gSum[bucket] += g;
			bSum[bucket] += b;
		}

		int bestBucket = -1;
		double bestWeight = 0.0;
		for (int i = 0; i < BUCKETS; i++)
		{
			if (weight[i] > bestWeight)
			{
				bestWeight = weight[i];
				bestBucket = i;
			}
		}

		if (bestBucket < 0)
		{
			return fallback;
		}

		final int n = count[bestBucket];
		final int r = (int) (rSum[bestBucket] / n);
		final int g = (int) (gSum[bestBucket] / n);
		final int b = (int) (bSum[bestBucket] / n);

		return boost(new Color(r, g, b));
	}

	private static Color boost(Color c)
	{
		float[] hsb = Color.RGBtoHSB(c.getRed(), c.getGreen(), c.getBlue(), null);
		hsb[1] = Math.min(1.0f, hsb[1] * 1.15f);
		hsb[2] = Math.min(1.0f, Math.max(0.4f, hsb[2]));
		return Color.getHSBColor(hsb[0], hsb[1], hsb[2]);
	}
}

